Create/Update Module Entry.code:
// Note: this adaptor targets the Zoho Analytics (Reports) API, not Zoho CRM.
// It can only add rows to a table (no updates), so this creates a new row.
addRow(
  // 1) Workspace (database) name.
  'health_programme',
  // 2) Table name, standing in for the CRM module.
  'Contacts',
  // 3) Column values for the new row.
  fields(
    field('Name', dataValue('name')),
    field('Phone', dataValue('phone')),
    field('District', dataValue('district'))
  )
);

Relate Module Entry.code:
// Note: this adaptor targets the Zoho Analytics (Reports) API, not Zoho CRM.
// It has no way to relate records, so the closest option is to add a row to a
// link table holding both ids.
addRow(
  // 1) Workspace (database) name.
  'health_programme',
  // 2) A table that stores the relationship.
  'Contact_Facility_Links',
  // 3) The two ids being related.
  fields(
    field('Contact_ID', dataValue('contactId')),
    field('Facility_ID', dataValue('facilityId'))
  )
);

Update Module Entry.code:
// Note: this adaptor targets the Zoho Analytics (Reports) API, not Zoho CRM.
// Not supported: the adaptor only exposes addRow, which inserts new rows.
// There is no function to update an existing row or module entry.
// If an append-only log is acceptable, add a new row with the latest values:
addRow(
  'health_programme',
  'Contacts_History',
  fields(
    field('Contact_ID', dataValue('contactId')),
    field('Status', dataValue('status')),
    field('Updated_At', new Date().toISOString())
  )
);

API Request (Beta).code:
// Note: this adaptor targets the Zoho Analytics (Reports) API, not Zoho CRM.
// Not supported: the adaptor has no generic request helper, only addRow
// (POST /{account}/{db}/{table} with ZOHO_ACTION=ADDROW).
addRow(
  'health_programme',
  'Visits',
  fields(field('Visit_Date', dataValue('visitDate')), field('Outcome', 'Completed'))
);

